changeSet.sql:
-- 1. Migrate Dialect -> LearningUnit INSERT INTO learning_unit (id, name, type, metadata_json, created_at, updated_at, created_by, updated_by) SELECT id, name, 'DIALECT', jsonb_build_object('description', description), created_at, updated_at, created_by, updated_by FROM dialect;
-- 2. Migrate Level -> LearningUnit INSERT INTO learning_unit (id, parent_id, name, type, metadata_json, created_at, updated_at, created_by, updated_by) SELECT id, dialect_id, name, 'LEVEL', jsonb_build_object( 'level_order', level_order, 'min_stars_required', min_stars_required, 'error_tag_id', error_tag_id, 'ai_threshold', ai_threshold, 'audio_url', audio_url, 'status', status, 'rejection_reason', rejection_reason ), created_at, updated_at, created_by, updated_by FROM level;
-- 3. Migrate Challenge -> ContentItem INSERT INTO content_item (id, learning_unit_id, title, type, status, metadata_json, created_at, updated_at, created_by, updated_by) SELECT id, level_id, CASE WHEN length(content_text) > 255 THEN substring(content_text from 1 for 252) || '...' ELSE content_text END, 'PRONUNCIATION', status, jsonb_build_object( 'content_text', content_text, 'phonetic_transcription_ipa', phonetic_transcription_ipa, 'reference_audio_url', reference_audio_url, 'focus_phonemes', focus_phonemes, 'skill_type', skill_type, 'difficulty', difficulty, 'rejection_reason', rejection_reason ), created_at, updated_at, created_by, updated_by FROM challenge;
-- 4. Migrate Quiz -> ContentItem INSERT INTO content_item (id, learning_unit_id, title, type, status, metadata_json, items_json, created_at, updated_at, created_by, updated_by) SELECT q.id, q.level_id, q.title, 'QUIZ', q.status, jsonb_build_object( 'description', q.description, 'instructions', q.instructions, 'passing_score', q.passing_score, 'time_limit_minutes', q.time_limit_minutes, 'rejection_reason', q.rejection_reason ), ( SELECT jsonb_agg(jsonb_build_object( 'skill_type', q_q.skill_type, 'difficulty', q_q.difficulty, 'question_order', q_q.question_order, 'points', q_q.points, 'challenge_id', q_q.challenge_id )) FROM quiz_question q_q WHERE q_q.quiz_id = q.id ), q.created_at, q.updated_at, q.created_by, q.updated_by FROM quiz q;
